"""Read a user-supplied PE and report metadata; never load or execute the DLL.

Known sample annotations are gated by the complete file SHA-256. They must not
be interpreted as offsets for a different Steam version or as runtime evidence.
"""
import argparse
import hashlib
import json
from pathlib import Path
import struct

KNOWN = '25a1975363e587f7c64eee7cf2fdcb02eb7511e178f1ae0b38783322a2bd6339'


def inspect(path):
    raw = path.read_bytes()
    if len(raw) < 64 or raw[:2] != b'MZ':
        raise ValueError('Not a DOS/PE image')
    pe = struct.unpack_from('<I', raw, 60)[0]
    if raw[pe:pe+4] != b'PE\0\0':
        raise ValueError('Missing PE signature')
    machine, count = struct.unpack_from('<HH', raw, pe+4)
    optional_size = struct.unpack_from('<H', raw, pe+20)[0]
    optional = pe+24
    magic = struct.unpack_from('<H', raw, optional)[0]
    if magic != 0x10b or machine != 0x14c:
        raise ValueError('This inspector expects an x86 PE32 sample')
    image_base = struct.unpack_from('<I', raw, optional+28)[0]
    sections = []
    for i in range(count):
        offset = optional+optional_size+40*i
        name = raw[offset:offset+8].rstrip(b'\0').decode('ascii')
        virtual_size, rva, size, file_offset = struct.unpack_from('<IIII', raw, offset+8)
        if file_offset+size > len(raw):
            raise ValueError('Section extends past file')
        sections.append(dict(name=name, rva=rva, virtual_size=virtual_size,
                             size=size, file_offset=file_offset))

    def offset(rva):
        for section in sections:
            delta = rva-section['rva']
            if 0 <= delta < section['size']:
                return section['file_offset']+delta
        raise ValueError('RVA is not file-backed')

    def string(rva):
        start = offset(rva)
        end = raw.index(0, start, min(start+4096, len(raw)))
        return raw[start:end].decode('ascii')

    export_rva = struct.unpack_from('<I', raw, optional+96)[0]
    exports = {}
    if export_rva:
        e = offset(export_rva)
        _, functions, names, function_table, name_table, ordinal_table = struct.unpack_from('<IIIIII', raw, e+16)
        for i in range(names):
            name_rva = struct.unpack_from('<I', raw, offset(name_table)+4*i)[0]
            ordinal = struct.unpack_from('<H', raw, offset(ordinal_table)+2*i)[0]
            if ordinal >= functions:
                raise ValueError('Invalid export ordinal')
            target = struct.unpack_from('<I', raw, offset(function_table)+4*ordinal)[0]
            exports[string(name_rva)] = hex(target)
    digest = hashlib.sha256(raw).hexdigest()
    report = dict(bytes=len(raw), sha256=digest, machine=hex(machine),
                  image_base=hex(image_base), exports=exports,
                  known_sample=digest == KNOWN, executed=False)
    if digest == KNOWN:
        start, end = 0x20a0, 0x20b3
        report['known_sample_annotations'] = {
            'interface_string': 'SteamFriends017',
            'flat_web_export_rva': '0x20a0',
            'flat_calling_convention': 'x86 cdecl; self, URL pointer, int32 mode',
            'virtual_call': 'ECX=self; push mode; push URL; call [vtable+0x78]',
            'virtual_slot_index': 30,
            'virtual_calling_convention': 'x86 thiscall; URL pointer, int32 mode',
            'flat_thunk_bytes_sha256': hashlib.sha256(raw[offset(start):offset(end)]).hexdigest(),
            'friends_accessor_export_rva': '0x5800',
            'find_or_create_user_interface_rva': '0xa3a0',
            'steamclient_getfriends_flat_export_rva': '0x1980',
            'claim_scope': 'static sample ABI only; actual game interface/request path not established',
            'runtime_interface_object': 'returned by installed Steam client; not present in this API DLL',
        }
    return report


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('dll', type=Path)
    args = parser.parse_args()
    print(json.dumps(inspect(args.dll), indent=2))
